INSERT INTO artwork_artists(artwork_id,artist_id,attribution_role,representative_order)
SELECT aw.id,a.id,'primary',1 FROM (VALUES
 ('van-eyck-annunciation','jan-van-eyck'),
 ('leonardo-ginevra-de-benci','leonardo-da-vinci'),
 ('artemisia-judith-beheading-holofernes','artemisia-gentileschi'),
 ('rembrandt-self-portrait-1660','rembrandt'),
 ('hokusai-great-wave','katsushika-hokusai'),
 ('monet-bridge-over-a-pond-of-water-lilies','claude-monet'),
 ('kroyer-summer-evening-skagen','p-s-kroyer'),
 ('anna-ancher-sunlight-blue-room','anna-ancher'),
 ('hilma-ten-largest-childhood-2','hilma-af-klint'),
 ('munch-the-scream-1893','edvard-munch')
) seed(work_slug,artist_slug) JOIN artworks aw ON aw.slug=seed.work_slug JOIN artists a ON a.slug=seed.artist_slug
WHERE NOT EXISTS(SELECT 1 FROM artwork_artists existing WHERE existing.artwork_id=aw.id AND existing.artist_id=a.id)
ON CONFLICT DO NOTHING;

