UPDATE artworks aw SET primary_media_id=ma.id,updated_at=now(),revision=aw.revision+1
FROM (VALUES
 ('van-eyck-annunciation','/assets/artworks/van-eyck-annunciation.jpg'),
 ('leonardo-ginevra-de-benci','/assets/artworks/leonardo-ginevra.jpg'),
 ('artemisia-judith-beheading-holofernes','/assets/artworks/artemisia-judith.jpg'),
 ('rembrandt-self-portrait-1660','/assets/artworks/rembrandt-self.jpg'),
 ('hokusai-great-wave','/assets/artworks/hokusai-wave.jpg'),
 ('monet-bridge-over-a-pond-of-water-lilies','/assets/artworks/monet-bridge.jpg'),
 ('kroyer-summer-evening-skagen','/assets/artworks/kroyer-evening.jpg'),
 ('anna-ancher-sunlight-blue-room','/assets/artworks/anna-blue.jpg'),
 ('hilma-ten-largest-childhood-2','/assets/artworks/hilma-childhood.jpg'),
 ('munch-the-scream-1893','/assets/artworks/munch-scream.png'),
 ('giotto-lamentation','/assets/artworks/giotto-lamentation.jpg'),
 ('giotto-meeting-at-the-golden-gate','/assets/artworks/giotto-gate.jpg'),
 ('giotto-massacre-of-the-innocents','/assets/artworks/giotto-massacre.jpg'),
 ('giotto-last-judgement','/assets/artworks/giotto-judgement.jpg')
) seed(slug,path) JOIN media_assets ma ON ma.storage_path=seed.path
WHERE aw.slug=seed.slug AND aw.primary_media_id IS NULL AND aw.status='review' AND aw.revision=1;

