) seed(slug,field_name,source_slug,url,note)
JOIN artworks aw ON aw.slug=seed.slug JOIN sources s ON s.slug=seed.source_slug
WHERE NOT EXISTS(SELECT 1 FROM citations c WHERE c.entity_type='artwork' AND c.entity_id=aw.id AND c.field_name=seed.field_name AND c.source_url=seed.url);
